#include <iostream>
#include <vector>
#include <unordered_map>

int main() {
    std::vector<std::string> items = {"apple", "banana", "apple", "orange", "banana", "apple"};
    std::unordered_map<std::string, int> counts;

    for (const auto& item : items) counts[item]++;

    for (const auto& [name, count] : counts) {
        std::cout << name << ": " << count << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

struct PlayerScore {
    std::string name;
    int score;
};

int main() {
    std::vector<PlayerScore> leaderboard = {
        {"Alex", 450}, {"Zara", 890}, {"Leo", 620}
    };

    std::sort(leaderboard.begin(), leaderboard.end(), [](const PlayerScore& a, const PlayerScore& b) {
        return a.score > b.score;
    });

    for (const auto& p : leaderboard) std::cout << p.name << " : " << p.score << "\n";
    return 0;
}

#include <iostream>

class Player {
private:
    std::string name;
    int health;
public:
    Player(std::string n, int h) : name(n), health(h) {}
    void takeDamage(int dmg) { health = std::max(0, health - dmg); }
    void display() const { std::cout << name << " | Health: " << health << "\n"; }
};

int main() {
    Player p1("Ghost", 100);
    p1.takeDamage(35);
    p1.display();
    return 0;
}

