#include <iostream>
#include <stdexcept>

double safeDivide(double a, double b) {
    if (b == 0.0) throw std::runtime_error("ZeroDivisionError: Cannot divide by zero!");
    return a / b;
}

int main() {
    try {
        std::cout << safeDivide(10, 2) << "\n";
        std::cout << safeDivide(5, 0) << "\n";
    } catch (const std::exception& e) {
        std::cerr << "Caught error: " << e.what() << "\n";
    }
    return 0;
}

